// === SOURCE VALIDATOR v6 ===
// Validates all 7 sources, logs quality, provides graceful fallbacks.

const _errs = [];
const _warns = [];
const all = items.map(i => i.json);

try {
  const src = {
    regresion: all.filter(r => r.pendiente !== undefined && r.r2 !== undefined),
    ema: all.filter(r => r.ema_ultimo !== undefined || (r.p5 !== undefined && r.p50 !== undefined)),
    markov: all.filter(r => r.status_from !== undefined && r.status_to !== undefined),
    llegadas: all.filter(r => r.contactos !== undefined && r.fecha !== undefined),
    inversiones: [],
    llamadas: [],
    horarios: []
  };
  const matched = new Set([...src.regresion, ...src.ema, ...src.markov, ...src.llegadas]);
  all.filter(r => !matched.has(r)).forEach(r => {
    const keys = Object.keys(r).join('|').toLowerCase();
    if (r.campaign !== undefined) src.inversiones.push(r);
    else if (keys.includes('hora') || keys.includes('hour') || keys.includes('probabilidad')) src.horarios.push(r);
    else src.llamadas.push(r);
  });

  const checks = [
    { name: 'regresion', min: 1, data: src.regresion },
    { name: 'ema', min: 1, data: src.ema },
    { name: 'markov', min: 10, data: src.markov },
    { name: 'llegadas', min: 7, data: src.llegadas },
    { name: 'inversiones', min: 1, data: src.inversiones },
    { name: 'llamadas', min: 1, data: src.llamadas },
    { name: 'horarios', min: 1, data: src.horarios }
  ];

  checks.forEach(c => {
    if (c.data.length === 0) _warns.push(c.name + ': SIN DATOS (0 registros)');
    else if (c.data.length < c.min) _warns.push(c.name + ': datos insuficientes (' + c.data.length + '/' + c.min + ')');
  });

  const validation = {
    total_items: all.length,
    sources: Object.fromEntries(Object.entries(src).map(([k, v]) => [k, v.length])),
    all_sources_have_data: Object.values(src).every(v => v.length > 0),
    errors: _errs,
    warnings: _warns,
    validated_at: new Date().toISOString()
  };

  return items.map(i => ({ json: { ...i.json, _source_validation: validation } }));
} catch(e) {
  _errs.push('SourceValidator crash: ' + e.message);
  return items.map(i => ({ json: { ...i.json, _source_validation: { total_items: all.length, errors: _errs, warnings: _warns, validated_at: new Date().toISOString() } } }));
}

// === FACTS BUILDER v7 ===
// Receives ALL items from ALL 7 MySQL sources (concatenated via merge tree).
// Each computational section wrapped in try/catch for resilience.

const _fb_errors = [];
const all = items.map(i => i.json);

// --- Source identification by field signatures ---
const src = {
  regresion: all.filter(r => r.pendiente !== undefined && r.r2 !== undefined),
  ema: all.filter(r => r.ema_ultimo !== undefined || (r.p5 !== undefined && r.p50 !== undefined)),
  markov: all.filter(r => r.status_from !== undefined && r.status_to !== undefined),
  llegadas: all.filter(r => r.contactos !== undefined && r.fecha !== undefined),
  inversiones: [],
  llamadas: [],
  horarios: []
};

const matched = new Set([...src.regresion, ...src.ema, ...src.markov, ...src.llegadas]);
const unmatched = all.filter(r => !matched.has(r));

unmatched.forEach(r => {
  const keys = Object.keys(r).join('|').toLowerCase();
  if (r.campaign !== undefined) {
    src.inversiones.push(r);
  } else if (keys.includes('hora') || keys.includes('hour') || keys.includes('probabilidad')) {
    src.horarios.push(r);
  } else {
    src.llamadas.push(r);
  }
});

const quality = {
  total_items: all.length,
  sources: Object.fromEntries(Object.entries(src).map(([k, v]) => [k, v.length])),
  all_sources_have_data: Object.values(src).every(v => v.length > 0)
};

// --- PROJECTIONS ---
const projections = { available: false };
if (src.regresion.length > 0) {
  projections.available = true;
  const latest = src.regresion[src.regresion.length - 1];
  projections.slope = parseFloat(latest.pendiente) || 0;
  projections.intercept = parseFloat(latest.intercepto) || 0;
  projections.r2 = parseFloat(latest.r2) || 0;
  projections.r2_label = projections.r2 >= 0.85 ? 'fuerte' : projections.r2 >= 0.6 ? 'moderado' : 'debil';
  projections.direction = projections.slope > 0.5 ? 'creciente' : projections.slope < -0.5 ? 'decreciente' : 'estable';
  if (src.regresion.length > 1) {
    const prev = src.regresion[src.regresion.length - 2];
    const delta = projections.slope - (parseFloat(prev.pendiente) || 0);
    projections.acceleration = delta > 0.1 ? 'acelerando' : delta < -0.1 ? 'desacelerando' : 'constante';
  }
  projections.history_points = src.regresion.length;
}
if (src.ema.length > 0) {
  const latestEma = src.ema[src.ema.length - 1];
  projections.ema_current = parseFloat(latestEma.ema_ultimo) || 0;
  projections.p5 = parseFloat(latestEma.p5) || 0;
  projections.p50 = parseFloat(latestEma.p50) || 0;
  projections.p95 = parseFloat(latestEma.p95) || 0;
  projections.spread = projections.p95 - projections.p5;
  projections.spread_pct = projections.p50 > 0 ? Math.round(projections.spread / projections.p50 * 10000) / 100 : 0;
  projections.confidence = projections.spread_pct < 50 ? 'alta' : projections.spread_pct < 80 ? 'media' : 'baja';
}


  // --- Matrix algebra utilities (for Fourier regression + Markov Fundamental) ---
  function _matInv(m) {
    const n = m.length;
    const a = m.map((r, i) => [...r, ...Array(n).fill(0).map((_, j) => i === j ? 1 : 0)]);
    for (let c = 0; c < n; c++) {
      let mx = c;
      for (let r = c + 1; r < n; r++) if (Math.abs(a[r][c]) > Math.abs(a[mx][c])) mx = r;
      [a[c], a[mx]] = [a[mx], a[c]];
      if (Math.abs(a[c][c]) < 1e-10) return null;
      const pv = a[c][c];
      for (let j = 0; j < 2 * n; j++) a[c][j] /= pv;
      for (let r = 0; r < n; r++) { if (r === c) continue; const f = a[r][c]; for (let j = 0; j < 2 * n; j++) a[r][j] -= f * a[c][j]; }
    }
    return a.map(r => r.slice(n));
  }
  function _matMul(A, B) {
    return A.map((row, i) => B[0].map((_, j) => row.reduce((s, a, k) => s + a * B[k][j], 0)));
  }
  function _matVecMul(A, v) {
    return A.map(row => row.reduce((s, a, k) => s + a * v[k], 0));
  }

// --- FUNNEL ---
const funnel = { available: false };
if (src.markov.length > 0) {
  funnel.available = true;
  const sample = src.markov[0];
  const pF = ['transition_pct','pct','percentage','percent'].find(f => sample[f] !== undefined) || 'pct';
  const cF = ['cnt','count','total'].find(f => sample[f] !== undefined) || 'cnt';

  const byFrom = {};
  src.markov.forEach(r => {
    const from = r.status_from || '';
    if (!byFrom[from]) byFrom[from] = [];
    byFrom[from].push({ to: r.status_to || '', pct: parseFloat(r[pF]) || 0, cnt: parseInt(r[cF]) || 0 });
  });

  const _toStatesSet = new Set(src.markov.map(r => r.status_to || '').filter(s => s));
  funnel.states = [...new Set([...Object.keys(byFrom), ..._toStatesSet])];
  funnel.transition_count = src.markov.length;

  // Biggest leaks (transitions to loss states)
  const leaks = [];
  src.markov.forEach(r => {
    const to = (r.status_to || '').toLowerCase();
    if (to.includes('lost') || to.includes('no show') || to.includes('disqualif')) {
      leaks.push({ from: r.status_from, to: r.status_to, pct: parseFloat(r[pF]) || 0, cnt: parseInt(r[cF]) || 0 });
    }
  });
  leaks.sort((a, b) => b.cnt - a.cnt);
  funnel.top_leaks = leaks.slice(0, 5);
  funnel.biggest_leak = leaks[0] || null;

  // Trap states (self-loop > 50%)
  funnel.trap_states = [];
  Object.entries(byFrom).forEach(([from, trans]) => {
    const self = trans.find(t => t.to === from);
    if (self && self.pct > 50) funnel.trap_states.push({ state: from, self_pct: self.pct, leads: self.cnt });
  });

  // Feeders to conversion
  const convState = funnel.states.find(s => s.toLowerCase().includes('consult booked') || s.toLowerCase().includes('won'));
  funnel.conversion_target = convState || 'Consult Booked';
  funnel.feeders = [];
  Object.entries(byFrom).forEach(([from, trans]) => {
    const hit = trans.find(t => t.to === funnel.conversion_target);
    if (hit) funnel.feeders.push({ from, pct: hit.pct, cnt: hit.cnt });
  });
  funnel.feeders.sort((a, b) => b.pct - a.pct);

  // Summary per state
  funnel.summary = Object.entries(byFrom).map(([from, trans]) => ({
    from, top: trans.sort((a, b) => b.pct - a.pct).slice(0, 5)
  }));

  // --- Absorbing Markov Chain: Fundamental Matrix N = (I-Q)^-1 ---
  const _absorbingNames = [];
  const _transitoryNames = [];
  const _allStates = funnel.states;

  _allStates.forEach(s => {
    const sl = s.toLowerCase();
    const _ABS_SET = new Set(['consult booked', 'won', 'closed lost', 'no show', 'disqualified', 'cancelled']);
    const _slNorm = sl.replace(/[^a-z0-9 ]/g, ' ').replace(/ +/g, ' ').trim();
    const isAbsorbing = _ABS_SET.has(sl) || _ABS_SET.has(_slNorm);
    if (isAbsorbing) _absorbingNames.push(s);
    else _transitoryNames.push(s);
  });

  funnel.markov_analysis = { available: false };

  if (_transitoryNames.length > 0 && _transitoryNames.length <= 25 && _absorbingNames.length > 0) {
    const _tN = _transitoryNames.length;
    const _aN = _absorbingNames.length;

    const _Q = Array.from({length: _tN}, () => Array(_tN).fill(0));
    const _R = Array.from({length: _tN}, () => Array(_aN).fill(0));

    _transitoryNames.forEach((from, fi) => {
      const trans = byFrom[from] || [];
      const totalPct = trans.reduce((s, t) => s + t.pct, 0);
      const scale = totalPct > 0 ? 100 / totalPct : 1;
      trans.forEach(t => {
        const tiIdx = _transitoryNames.indexOf(t.to);
        const aiIdx = _absorbingNames.indexOf(t.to);
        const prob = (t.pct / 100) * (scale > 0 ? 100 / totalPct : 1);
        if (tiIdx >= 0) _Q[fi][tiIdx] = t.pct / totalPct;
        if (aiIdx >= 0) _R[fi][aiIdx] = t.pct / totalPct;
      });
    });

    const _ImQ = Array.from({length: _tN}, (_, i) =>
      Array.from({length: _tN}, (_, j) => (i === j ? 1 : 0) - _Q[i][j])
    );

    const _N = _matInv(_ImQ);

    if (_N) {
      const _B = _matMul(_N, _R);
      const _ones = Array(_tN).fill(1);
      const _expSteps = _matVecMul(_N, _ones);

      const convAbsIdx = _absorbingNames.findIndex(s =>
        s.toLowerCase().includes('consult booked') || s.toLowerCase().includes('won')
      );

      funnel.markov_analysis = {
        available: true,
        transitory_states: _transitoryNames,
        absorbing_states: _absorbingNames,
        conversion_absorbing: convAbsIdx >= 0 ? _absorbingNames[convAbsIdx] : null,
        absorption_probabilities: _transitoryNames.map((s, i) => ({
          state: s,
          prob_conversion: convAbsIdx >= 0 ? Math.round(_B[i][convAbsIdx] * 10000) / 10000 : null,
          prob_loss: convAbsIdx >= 0 ? Math.round((1 - _B[i][convAbsIdx]) * 10000) / 10000 : null,
          expected_steps: Math.round(_expSteps[i] * 100) / 100
        })),
        entry_state_conversion: null
      };

      const entryIdx = _transitoryNames.findIndex(s =>
        s.toLowerCase().includes('new lead') || s.toLowerCase().includes('open') || s.toLowerCase().includes('new') || s.toLowerCase().includes('entrada') || s.toLowerCase().includes('fresh')
      );
      if (entryIdx >= 0 && convAbsIdx >= 0) {
        funnel.markov_analysis.entry_state_conversion = Math.round(_B[entryIdx][convAbsIdx] * 10000) / 10000;
        funnel.markov_analysis.entry_expected_steps = Math.round(_expSteps[entryIdx] * 100) / 100;

      // --- Research v3: Absorption time variance ---
      const _tVarVec = [];
      for (let _vi = 0; _vi < _tN; _vi++) {
        let _nds = 0;
        for (let _vj = 0; _vj < _tN; _vj++) _nds += _N[_vi][_vj] * _N[_vj][_vj];
        _tVarVec.push(Math.max(0, (2 * _nds) - _expSteps[_vi] - Math.pow(_expSteps[_vi], 2)));
      }
      if (entryIdx >= 0) {
        const _eVar = _tVarVec[entryIdx];
        const _eStd = Math.sqrt(_eVar);
        funnel.markov_analysis.entry_step_variance = Math.round(_eVar * 100) / 100;
        funnel.markov_analysis.entry_step_stddev = Math.round(_eStd * 100) / 100;
        funnel.markov_analysis.entry_step_cv = _expSteps[entryIdx] > 0 ? Math.round((_eStd / _expSteps[entryIdx]) * 1000) / 1000 : 0;
      }
      funnel.markov_analysis.absorption_probabilities.forEach(function(_ap, _ai) {
        _ap.step_variance = Math.round(_tVarVec[_ai] * 100) / 100;
        _ap.step_stddev = Math.round(Math.sqrt(_tVarVec[_ai]) * 100) / 100;
      });
      }
    }
  }
}

// --- OPERATIONS ---
const operations = { available: false };
if (src.llegadas.length > 0) {
  operations.available = true;
  const sorted = [...src.llegadas].sort((a, b) => new Date(a.fecha) - new Date(b.fecha));
  const vols = sorted.map(r => parseInt(r.contactos) || 0);
  const total = vols.reduce((a, b) => a + b, 0);
  operations.total_days = vols.length;
  operations.total_leads = total;
  operations.avg_daily = Math.round(total / vols.length * 100) / 100;
  operations.latest = { date: sorted[sorted.length-1].fecha, leads: vols[vols.length-1] };
  operations.min_daily = Math.min(...vols);
  operations.max_daily = Math.max(...vols);
  if (vols.length >= 14) {
    const w1 = vols.slice(-7), w2 = vols.slice(-14, -7);
    const a1 = w1.reduce((a,b)=>a+b,0)/7, a2 = w2.reduce((a,b)=>a+b,0)/7;
    operations.last_7d_avg = Math.round(a1*100)/100;
    operations.prev_7d_avg = Math.round(a2*100)/100;
    operations.wow_change_pct = Math.round((a1-a2)/a2*10000)/100;
  }
  operations.recent_trend = vols.length >= 6 ?
    (vols.slice(-3).reduce((a,b)=>a+b,0)/3 > vols.slice(-6,-3).reduce((a,b)=>a+b,0)/3*1.1 ? 'creciente' : vols.slice(-3).reduce((a,b)=>a+b,0)/3 < vols.slice(-6,-3).reduce((a,b)=>a+b,0)/3*0.9 ? 'decreciente' : 'estable') : 'sin_datos';
}

if (src.horarios.length > 0) {
  const hKeys = Object.keys(src.horarios[0]);
  const hF = hKeys.find(k => k.toLowerCase().includes('hora') || k.toLowerCase().includes('hour')) || hKeys[0];
  const vF = hKeys.find(k => k !== hF && typeof src.horarios[0][k] === 'number') || hKeys[1];
  const ranked = src.horarios.map(h => ({ hour: h[hF], value: parseFloat(h[vF])||0 })).sort((a,b) => b.value - a.value);
  operations.peak_hour = ranked[0]?.hour;
  operations.valley_hour = ranked[ranked.length-1]?.hour;
  operations.hourly_top3 = ranked.slice(0,3);
}

if (src.llamadas.length > 0) {
  var _cr = src.llamadas[0];
  if (_cr.total_records !== undefined) {
    operations.call_records = parseInt(_cr.total_records) || 0;
    operations.call_rows_returned = src.llamadas.length;
    operations.call_data_note = 'Pre-agregado: ' + operations.call_records + ' registros en ' + src.llamadas.length + ' fila(s) SQL';
    operations.unique_contacts = parseInt(_cr.unique_contacts) || 0;
    operations.call_metrics = {
      call_duration: { min: parseFloat(_cr.call_duration_min)||0, avg: Math.round((parseFloat(_cr.call_duration_avg)||0)*100)/100, max: parseFloat(_cr.call_duration_max)||0, std: Math.round((parseFloat(_cr.call_duration_std)||0)*100)/100 },
      minutes_since_prev: { min: parseFloat(_cr.minutes_since_prev_min)||0, avg: Math.round((parseFloat(_cr.minutes_since_prev_avg)||0)*100)/100, max: parseFloat(_cr.minutes_since_prev_max)||0 },
      call_rank: { min: parseFloat(_cr.call_rank_min)||0, avg: Math.round((parseFloat(_cr.call_rank_avg)||0)*100)/100, max: parseFloat(_cr.call_rank_max)||0 }
    };
    operations.contact_distribution = {
      first_attempts: parseInt(_cr.first_attempts)||0,
      attempts_1_to_3: parseInt(_cr.attempts_1_to_3)||0,
      attempts_1_to_5: parseInt(_cr.attempts_1_to_5)||0,
      overcontact_calls: parseInt(_cr.overcontact_calls)||0,
      overcontact_pct: operations.call_records > 0 ? Math.round((parseInt(_cr.overcontact_calls)||0) / operations.call_records * 10000) / 100 : 0
    };
  } else {
    operations.call_records = src.llamadas.length;
    var _ckF = Object.keys(src.llamadas[0]).filter(function(k) { return typeof src.llamadas[0][k] === 'number'; });
    operations.call_metrics = {};
    _ckF.forEach(function(f) {
      var vals = src.llamadas.map(function(r) { return parseFloat(r[f]); }).filter(function(v) { return !isNaN(v); });
      if (vals.length) operations.call_metrics[f] = { min: Math.min.apply(null, vals), avg: Math.round(vals.reduce(function(a,b){return a+b;},0)/vals.length*100)/100, max: Math.max.apply(null, vals) };
    });
  }
}

// --- INVESTMENT (spend-only: inversiones_campanas has no leads column) ---
const investment = { available: false, cpl_available: false };
if (src.inversiones.length > 0) {
  investment.available = true;
  const byCamp = {};
  src.inversiones.forEach(c => {
    const name = c.campaign || 'unknown';
    const sp = parseFloat(c.spend) || 0;
    if (!byCamp[name]) byCamp[name] = { name, spend: 0, records: 0, source: c.source || c.datasource || '' };
    byCamp[name].spend += sp;
    byCamp[name].records++;
  });
  investment.campaigns = Object.values(byCamp).sort((a, b) => b.spend - a.spend);
  investment.total_spend = investment.campaigns.reduce((s, c) => s + c.spend, 0);
  investment.campaign_count = investment.campaigns.length;
  if (investment.total_spend > 0) {
    investment.campaigns.forEach(c => { c.pct_of_total = Math.round(c.spend / investment.total_spend * 10000) / 100; });
    investment.top_spender = investment.campaigns[0];
    investment.lowest_spender = investment.campaigns[investment.campaigns.length - 1];
    investment.top_concentration_pct = investment.campaigns[0].pct_of_total;
  }

  // --- Marketing Mix Model (Adstock + Hill + Granger + Ridge) ---
  investment.mmm = { available: false };

  const _invDaily = {};
  src.inversiones.forEach(r => {
    const camp = r.campaign || 'unknown';
    const fecha = r.fecha_gasto || r.fecha || null;
    const spend = parseFloat(r.spend) || 0;
    if (!fecha || spend <= 0) return;
    const dateStr = typeof fecha === 'string' ? fecha.split('T')[0] : new Date(fecha).toISOString().split('T')[0];
    if (!_invDaily[camp]) _invDaily[camp] = {};
    _invDaily[camp][dateStr] = (_invDaily[camp][dateStr] || 0) + spend;
  });

  const _campNames = Object.keys(_invDaily);
  const _hasDailySpend = _campNames.length > 0 && _campNames.some(c => Object.keys(_invDaily[c]).length >= 7);

  if (_hasDailySpend && src.llegadas.length >= 14) {
    const _leadsSorted = [...src.llegadas].sort((a, b) => new Date(a.fecha) - new Date(b.fecha));
    const _leadDates = _leadsSorted.map(r => {
      const f = r.fecha;
      return typeof f === 'string' ? f.split('T')[0] : new Date(f).toISOString().split('T')[0];
    });
    const _leadVols = _leadsSorted.map(r => parseInt(r.contactos) || 0);
    const _nLead = _leadVols.length;

    // Build aligned daily spend vectors per campaign
    const _campSpend = {};
    _campNames.forEach(camp => {
      _campSpend[camp] = _leadDates.map(d => _invDaily[camp][d] || 0);
    });

    // Adstock transformation: A_t = spend_t + theta * A_{t-1}
    function _adstock(series, theta) {
      const out = [series[0]];
      for (let t = 1; t < series.length; t++) {
        out.push(series[t] + theta * out[t - 1]);
      }
      return out;
    }

    // Hill saturation: S = A^gamma / (A^gamma + K^gamma)
    function _hill(series, gamma, K) {
      return series.map(a => {
        if (a <= 0) return 0;
        const ag = Math.pow(a, gamma);
        return ag / (ag + Math.pow(K, gamma));
      });
    }

    // Apply Adstock with theta=0.3 (3-day half-life) and Hill with auto K
    const _thetaDecay = 0.3;
    const _gammaHill = 0.8;
    const _campTransformed = {};
    _campNames.forEach(camp => {
      const raw = _campSpend[camp];
      const adstocked = _adstock(raw, _thetaDecay);
      const maxAd = Math.max(...adstocked);
      const K = maxAd > 0 ? maxAd * 0.5 : 1;
      _campTransformed[camp] = _hill(adstocked, _gammaHill, K);
    });

    // --- Simplified Granger Causality via F-test ---
    // Restricted model: leads_t ~ intercept + lag1_leads + lag7_leads
    // Unrestricted model: leads_t ~ intercept + lag1_leads + lag7_leads + sum(spend_lags)
    // F = ((RSS_r - RSS_u) / q) / (RSS_u / (n - p))
    const _grangerResults = {};
    const _minLag = 7;

    if (_nLead > _minLag + 10) {
      // Build restricted model (leads only)
      const _yG = [], _XrG = [];
      for (let t = _minLag; t < _nLead; t++) {
        _yG.push(_leadVols[t]);
        _XrG.push([1, _leadVols[t - 1], _leadVols[t - 7]]);
      }
      const _nG = _yG.length;
      const _pR = 3;

      // OLS for restricted
      function _olsRSS(X, y) {
        const p = X[0].length;
        const Xt = Array.from({length: p}, (_, i) => X.map(r => r[i]));
        const XtX = Array.from({length: p}, (_, i) =>
          Array.from({length: p}, (_, j) => Xt[i].reduce((s, _, k) => s + Xt[i][k] * Xt[j][k], 0))
        );
        const XtY = Xt.map(col => col.reduce((s, v, k) => s + v * y[k], 0));
        const inv = _matInv(XtX);
        if (!inv) return { rss: Infinity, beta: null };
        const beta = _matVecMul(inv, XtY);
        let rss = 0;
        for (let i = 0; i < y.length; i++) {
          const pred = X[i].reduce((s, x, j) => s + x * beta[j], 0);
          rss += Math.pow(y[i] - pred, 2);
        }
        return { rss, beta };
      }

      const _rssRestricted = _olsRSS(_XrG, _yG).rss;

      _campNames.forEach(camp => {
        const trans = _campTransformed[camp];
        if (!trans) return;
        const _XuG = [];
        for (let t = _minLag; t < _nLead; t++) {
          _XuG.push([1, _leadVols[t - 1], _leadVols[t - 7], trans[t], trans[Math.max(0, t - 1)]]);
        }
        const _pU = 5;
        const _q = _pU - _pR;
        const _rssU = _olsRSS(_XuG, _yG).rss;

        if (_rssU < _rssRestricted && _rssU > 0) {
          const _fStat = ((_rssRestricted - _rssU) / _q) / (_rssU / (_nG - _pU));
          _grangerResults[camp] = {
            f_statistic: Math.round(_fStat * 100) / 100,
            rss_restricted: Math.round(_rssRestricted),
            rss_unrestricted: Math.round(_rssU),
            rss_improvement_pct: Math.round((_rssRestricted - _rssU) / _rssRestricted * 10000) / 100,
            likely_causal: _fStat > 3.0
          };
        } else {
          _grangerResults[camp] = { f_statistic: 0, likely_causal: false, rss_improvement_pct: 0 };
        }
      });

      // --- Ridge Regression for Attribution ---
      // y = intercept + sum(beta_i * transformed_spend_i) + lag_controls
      // (X'X + lambda*I)^-1 X'y
      const _lambda = 10;
      const _attrCamps = _campNames.filter(c => _grangerResults[c] && _grangerResults[c].rss_improvement_pct > 0);

      if (_attrCamps.length > 0) {
        const _yA = [], _XA = [];
        for (let t = _minLag; t < _nLead; t++) {
          const row = [1, _leadVols[t - 1], _leadVols[t - 7]];
          _attrCamps.forEach(c => row.push(_campTransformed[c][t]));
          _XA.push(row);
          _yA.push(_leadVols[t]);
        }
        const _pA = _XA[0].length;
        const _XtA = Array.from({length: _pA}, (_, i) => _XA.map(r => r[i]));
        const _XtXA = Array.from({length: _pA}, (_, i) =>
          Array.from({length: _pA}, (_, j) =>
            _XtA[i].reduce((s, _, k) => s + _XtA[i][k] * _XtA[j][k], 0) + (i === j && i >= 3 ? _lambda : 0)
          )
        );
        const _XtYA = _XtA.map(col => col.reduce((s, v, k) => s + v * _yA[k], 0));
        const _invA = _matInv(_XtXA);

        if (_invA) {
          const _betaA = _matVecMul(_invA, _XtYA);
          const _campCoefs = _attrCamps.map((c, i) => ({
            campaign: c,
            coefficient: Math.round(_betaA[3 + i] * 1000) / 1000,
            granger_f: _grangerResults[c].f_statistic,
            likely_causal: _grangerResults[c].likely_causal,
            rss_improvement_pct: _grangerResults[c].rss_improvement_pct
          }));
          _campCoefs.sort((a, b) => Math.abs(b.coefficient) - Math.abs(a.coefficient));

          // Total variance explained by spend vs autoregressive
          let _rssBase = 0, _rssFull = 0;
          for (let t = 0; t < _yA.length; t++) {
            const predBase = _XA[t][0] * _betaA[0] + _XA[t][1] * _betaA[1] + _XA[t][2] * _betaA[2];
            const predFull = _XA[t].reduce((s, x, j) => s + x * _betaA[j], 0);
            _rssBase += Math.pow(_yA[t] - predBase, 2);
            _rssFull += Math.pow(_yA[t] - predFull, 2);
          }
          const _spendContrib = _rssBase > 0 ? Math.round((_rssBase - _rssFull) / _rssBase * 10000) / 100 : 0;

          // HHI concentration index
          const _shares = investment.campaigns.map(c => c.pct_of_total / 100);
          const _hhi = Math.round(_shares.reduce((s, sh) => s + sh * sh, 0) * 10000) / 10000;

          investment.mmm = {
            available: true,
            method: 'Ridge_Adstock_Hill',
            adstock_theta: _thetaDecay,
            hill_gamma: _gammaHill,
            ridge_lambda: _lambda,
            hhi_index: _hhi,
            hhi_label: _hhi > 0.25 ? 'alta_concentracion' : _hhi > 0.15 ? 'moderada' : 'diversificada',
            spend_variance_contribution_pct: _spendContrib,
            campaign_attribution: _campCoefs,
            granger_results: _grangerResults,
            causal_campaigns: _campCoefs.filter(c => c.likely_causal).map(c => c.campaign),
            non_causal_campaigns: _campCoefs.filter(c => !c.likely_causal).map(c => c.campaign),
            recommendation: _hhi > 0.25
              ? 'Alta concentracion de gasto (HHI=' + _hhi + '). Diversificar para reducir riesgo.'
              : 'Concentracion de gasto aceptable (HHI=' + _hhi + ').'
          };
        }
      }

      if (!investment.mmm.available) {
        investment.mmm = {
          available: false,
          reason: 'Datos insuficientes: se necesitan >= 7 dias de gasto diario por campana con variacion',
          hhi_index: null
        };
        const _shares = investment.campaigns.map(c => (c.pct_of_total || 0) / 100);
        investment.mmm.hhi_index = Math.round(_shares.reduce((s, sh) => s + sh * sh, 0) * 10000) / 10000;
        investment.mmm.hhi_label = investment.mmm.hhi_index > 0.25 ? 'alta_concentracion' : investment.mmm.hhi_index > 0.15 ? 'moderada' : 'diversificada';
      }
    }
  }
}


// --- PREDICTION ENGINE V3 ---
// Multi-model forecasting with rolling backtest, MASE selection, empirical intervals.
// Primary source: src.llegadas. projections/ema are auxiliary cross-checks only.

const predictionV2 = { mode: 'unavailable' };

if (src.llegadas.length >= 14) {
  const _sorted = [...src.llegadas].sort((a, b) => new Date(a.fecha) - new Date(b.fecha));
  const _dates = _sorted.map(r => new Date(r.fecha));
  const _vols = _sorted.map(r => parseInt(r.contactos) || 0);
  const _n = _vols.length;

  const _volMean = _vols.reduce((a, b) => a + b, 0) / _n;
  const _volVar = _vols.reduce((s, v) => s + Math.pow(v - _volMean, 2), 0) / _n;
  const _volStd = Math.sqrt(_volVar);
  const _volCV = _volMean > 0 ? _volStd / _volMean : 0;

  predictionV2.volatility = {
    mean: Math.round(_volMean * 100) / 100,
    stddev: Math.round(_volStd * 100) / 100,
    cv_pct: Math.round(_volCV * 10000) / 100,
    label: _volCV < 0.15 ? 'muy_estable' : _volCV < 0.3 ? 'estable' : _volCV < 0.5 ? 'moderada' : 'alta'
  };

  // Day-of-week seasonal indices
  const _dowS = [0,0,0,0,0,0,0], _dowC = [0,0,0,0,0,0,0];
  for (let i = 0; i < _n; i++) { const d = _dates[i].getDay(); _dowS[d] += _vols[i]; _dowC[d]++; }
  const _dowA = _dowS.map((s, i) => _dowC[i] > 0 ? s / _dowC[i] : _volMean);
  const _dowGM = _dowA.reduce((a, b) => a + b, 0) / 7;
  const _sIdx = _dowA.map(a => _dowGM > 0 ? a / _dowGM : 1);

  // ---- Model definitions (all pure JS, no imports) ----
  function _mMean7(h, idx) {
    if (idx < 7) return null;
    return h.slice(idx - 7, idx).reduce((a, b) => a + b, 0) / 7;
  }
  function _mSNaive(h, idx) {
    return idx >= 7 ? h[idx - 7] : null;
  }
  function _mEWMA(h, idx) {
    if (idx < 2) return null;
    let e = h[0]; const alpha = 0.3;
    for (let i = 1; i < idx; i++) e = alpha * h[i] + (1 - alpha) * e;
    return e;
  }
  function _mTheta(h, idx, ds, si) {
    if (idx < 14) return null;
    const w = h.slice(0, idx);
    const dw = w.map((v, i) => { const d = ds[i].getDay(); return si[d] > 0 ? v / si[d] : v; });
    const wn = dw.length;
    let sx = 0, sy = 0, sxy = 0, sx2 = 0;
    for (let i = 0; i < wn; i++) { sx += i; sy += dw[i]; sxy += i * dw[i]; sx2 += i * i; }
    const sl = (wn * sxy - sx * sy) / (wn * sx2 - sx * sx || 1);
    const ic = (sy - sl * sx) / wn;
    const tz = ic + sl * wn;
    let ses = dw[0]; const sa = 0.2;
    for (let i = 1; i < wn; i++) ses = sa * dw[i] + (1 - sa) * ses;
    const combined = (tz + ses) / 2;
    const _tgtDate = idx < ds.length ? ds[idx] : new Date(ds[ds.length - 1].getTime() + 86400000);
    return combined * si[_tgtDate.getDay()];
  }
  function _mTSBlend(h, idx, ds, si) {
    if (idx < 7) return null;
    const r3 = idx >= 3 ? h.slice(idx - 3, idx).reduce((a, b) => a + b, 0) / 3 : h[idx - 1];
    const _bDate = idx < ds.length ? ds[idx] : new Date(ds[ds.length - 1].getTime() + 86400000);
    return r3 * si[_bDate.getDay()];
  }

  // --- Fourier Harmonic Regression (sin/cos + lag7 + OLS normal equations) ---
  function _mFourier(h, idx, ds) {
    if (idx < 14) return null;
    const P = 7, K = 2;
    const rows = [];
    const yVec = [];
    for (let t = 7; t < idx; t++) {
      const dow = ds[t].getDay();
      rows.push([
        1,
        Math.sin(2 * Math.PI * 1 * dow / P),
        Math.cos(2 * Math.PI * 1 * dow / P),
        Math.sin(2 * Math.PI * 2 * dow / P),
        Math.cos(2 * Math.PI * 2 * dow / P),
        h[t - 7]
      ]);
      yVec.push(h[t]);
    }
    if (rows.length < 10) return null;
    const nf = 6;
    const Xt = Array.from({length: nf}, (_, i) => rows.map(r => r[i]));
    const XtX = Array.from({length: nf}, (_, i) =>
      Array.from({length: nf}, (_, j) =>
        Xt[i].reduce((s, _, k) => s + Xt[i][k] * Xt[j][k], 0)
      )
    );
    const XtY = Xt.map(col => col.reduce((s, v, k) => s + v * yVec[k], 0));
    const inv = _matInv(XtX);
    if (!inv) return null;
    const beta = _matVecMul(inv, XtY);
    const _fDate = idx < ds.length ? ds[idx] : new Date(ds[ds.length - 1].getTime() + 86400000);
    const tgtDow = _fDate.getDay();
    const xNew = [
      1,
      Math.sin(2 * Math.PI * 1 * tgtDow / P),
      Math.cos(2 * Math.PI * 1 * tgtDow / P),
      Math.sin(2 * Math.PI * 2 * tgtDow / P),
      Math.cos(2 * Math.PI * 2 * tgtDow / P),
      h[idx - 7]
    ];
    return xNew.reduce((s, x, i) => s + x * beta[i], 0);
  }

  // --- Holt-Winters Additive (level + trend + weekly seasonality) ---
  function _mHW(h, idx) {
    if (idx < 14) return null;
    const P = 7;
    const w = h.slice(0, idx);
    const wn = w.length;
    const fw = w.slice(0, P);
    let L = fw.reduce((a, b) => a + b, 0) / P;
    let T = 0;
    if (wn >= 2 * P) {
      const sw = w.slice(P, 2 * P);
      T = (sw.reduce((a, b) => a + b, 0) / P - L) / P;
    }
    const S = fw.map(v => v - L);
    const alpha = 0.3, beta2 = 0.1, gamma2 = 0.2;
    for (let t = P; t < wn; t++) {
      const si = t % P;
      const y = w[t];
      const Ln = alpha * (y - S[si]) + (1 - alpha) * (L + T);
      const Tn = beta2 * (Ln - L) + (1 - beta2) * T;
      S[si] = gamma2 * (y - Ln) + (1 - gamma2) * S[si];
      L = Ln; T = Tn;
    }
    return L + T + S[wn % P];
  }

  const _models = [
    { name: 'mean_7d',           fn: (h, i) => _mMean7(h, i) },
    { name: 'seasonal_naive',    fn: (h, i) => _mSNaive(h, i) },
    { name: 'ewma',              fn: (h, i) => _mEWMA(h, i) },
    { name: 'theta_lite',        fn: (h, i) => _mTheta(h, i, _dates, _sIdx) },
    { name: 'trend_season',      fn: (h, i) => _mTSBlend(h, i, _dates, _sIdx) },
    { name: 'fourier_regression', fn: (h, i) => _mFourier(h, i, _dates) },
    { name: 'holt_winters',      fn: (h, i) => _mHW(h, i) }
  ];

  // ---- Rolling backtest (last 14 days, 1-step-ahead) ----
  const _btWin = Math.min(14, _n - 14);
  const _btStart = _n - _btWin;
  const _mRes = _models.map(m => ({ name: m.name, errors: [], abs: [], preds: [], acts: [] }));
  const _naiveErr = [];

  for (let i = _btStart; i < _n; i++) {
    if (i >= 7) _naiveErr.push(Math.abs(_vols[i] - _vols[i - 7]));
    for (let mi = 0; mi < _models.length; mi++) {
      const p = _models[mi].fn(_vols, i);
      if (p !== null && !isNaN(p)) {
        const e = _vols[i] - p;
        _mRes[mi].errors.push(e);
        _mRes[mi].abs.push(Math.abs(e));
        _mRes[mi].preds.push(Math.round(p));
        _mRes[mi].acts.push(_vols[i]);
      }
    }
  }

  const _naiveMAE = _naiveErr.length > 0 ? _naiveErr.reduce((a, b) => a + b, 0) / _naiveErr.length : _volStd;

  _mRes.forEach(mr => {
    if (mr.abs.length > 0) {
      mr.mae  = mr.abs.reduce((a, b) => a + b, 0) / mr.abs.length;
      mr.mase = _naiveMAE > 0 ? mr.mae / _naiveMAE : 999;
      mr.rmse = Math.sqrt(mr.errors.reduce((s, e) => s + e * e, 0) / mr.errors.length);
    } else { mr.mae = 999; mr.mase = 999; mr.rmse = 999; }
  });

  const _ranked = [..._mRes].sort((a, b) => a.mase - b.mase);
  const _best = _ranked[0];

  // ---- Ensemble (inverse-MASE weighted, top 3) ----
  const _top3 = _ranked.filter(m => m.mase < 999).slice(0, 3);
  const _totalInv = _top3.reduce((s, m) => s + 1 / Math.max(m.mase, 0.01), 0);
  const _ensW = _top3.map(m => ({
    name: m.name,
    weight: Math.round((1 / Math.max(m.mase, 0.01)) / _totalInv * 1000) / 1000
  }));

  const _fcasts = {};
  _models.forEach(m => {
    const p = m.fn(_vols, _n);
    if (p !== null && !isNaN(p)) _fcasts[m.name] = Math.round(Math.max(0, p));
  });

  let _ensFc = 0;
  _ensW.forEach(ew => { if (_fcasts[ew.name] !== undefined) _ensFc += _fcasts[ew.name] * ew.weight; });
  _ensFc = Math.round(Math.max(0, _ensFc));

  const _bestFc = _fcasts[_best.name] || _ensFc;
  const _useEns = _top3.length >= 2 && (_top3[1].mase / _top3[0].mase) < 1.2;
  const _selFc = _useEns ? _ensFc : _bestFc;
  const _selMethod = _useEns ? 'ensemble_weighted' : _best.name;

  // ---- Empirical intervals from backtest residuals ----
  const _residuals = _useEns
    ? _mRes.filter(m => _ensW.some(ew => ew.name === m.name)).flatMap(m => m.abs)
    : (_mRes.find(m => m.name === _best.name) || _mRes[0]).abs;

  const _sortedR = [..._residuals].sort((a, b) => a - b);

  function _quantile(sorted, q) {
    if (sorted.length === 0) return _volStd;
    const pos = (sorted.length - 1) * q;
    const lo = Math.floor(pos), hi = Math.ceil(pos);
    return lo === hi ? sorted[lo] : sorted[lo] + (pos - lo) * (sorted[hi] - sorted[lo]);
  }

  const _q50 = _quantile(_sortedR, 0.50);
  const _q80 = _quantile(_sortedR, 0.80);
  const _q95 = _quantile(_sortedR, 0.95);

  const _intervals = {
    band_50: { low: Math.round(Math.max(0, _selFc - _q50)), high: Math.round(_selFc + _q50) },
    band_80: { low: Math.round(Math.max(0, _selFc - _q80)), high: Math.round(_selFc + _q80) },
    band_95: { low: Math.round(Math.max(0, _selFc - _q95)), high: Math.round(_selFc + _q95) },
    residual_points: _sortedR.length
  };

  const _bestRes = _mRes.find(m => m.name === _best.name) || _mRes[0];
  let _covHits = 0;
  for (let i = 0; i < _bestRes.preds.length; i++) {
    if (Math.abs(_bestRes.acts[i] - _bestRes.preds[i]) <= _q80) _covHits++;
  }
  const _empCov = _bestRes.preds.length > 0 ? Math.round(_covHits / _bestRes.preds.length * 100) : 0;

  // --- Adaptive Conformal Inference (ACI) within backtest window ---
  let _aciAlpha = 0.2;
  const _aciGamma = 0.05;
  const _aciTargetAlpha = 0.2;
  const _aciResiduals = [..._sortedR];

  for (let bi = 0; bi < _bestRes.preds.length; bi++) {
    const _aciQ = _quantile(_aciResiduals, 1 - _aciAlpha);
    const _aciErr = Math.abs(_bestRes.acts[bi] - _bestRes.preds[bi]) > _aciQ ? 1 : 0;
    _aciAlpha = Math.max(0.01, Math.min(0.5, _aciAlpha + _aciGamma * (_aciTargetAlpha - _aciErr)));
  }

  const _aciQ80 = _quantile(_sortedR, 1 - _aciAlpha);
  const _aciIntervals = {
    aci_alpha: Math.round(_aciAlpha * 1000) / 1000,
    aci_band: { low: Math.round(Math.max(0, _selFc - _aciQ80)), high: Math.round(_selFc + _aciQ80) },
    aci_width_pct: _selFc > 0 ? Math.round(2 * _aciQ80 / _selFc * 10000) / 100 : 0,
    aci_vs_fixed: Math.round((2 * _aciQ80 - (_intervals.band_80.high - _intervals.band_80.low)) / Math.max(1, _intervals.band_80.high - _intervals.band_80.low) * 10000) / 100
  };

  // ---- Forecast horizons ----
  const _todayDow = new Date().getDay();
  const _horizons = {};
  _horizons.next_1d = {
    forecast: _selFc, band_low: _intervals.band_80.low, band_high: _intervals.band_80.high,
    confidence_pct: _empCov, method: _selMethod
  };
  let _s7 = 0; for (let d = 0; d < 7; d++) _s7 += _selFc * _sIdx[(_todayDow + d + 1) % 7];
  _s7 = Math.round(_s7);
  const _u7 = _q80 * Math.sqrt(7);
  _horizons.next_7d = {
    forecast: _s7, band_low: Math.round(Math.max(0, _s7 - _u7)),
    band_high: Math.round(_s7 + _u7), method: _selMethod + '+seasonal'
  };
  let _s14 = 0; for (let d = 0; d < 14; d++) _s14 += _selFc * _sIdx[(_todayDow + d + 1) % 7];
  _s14 = Math.round(_s14);
  const _u14 = _q80 * Math.sqrt(14);
  _horizons.next_14d = {
    forecast: _s14, band_low: Math.round(Math.max(0, _s14 - _u14)),
    band_high: Math.round(_s14 + _u14), method: _selMethod + '+seasonal'
  };

  // ---- Mode and confidence from backtest quality ----
  const _bMASE = _best.mase;
  if (_bMASE < 0.8) {
    predictionV2.mode = 'model'; predictionV2.confidence = 'alta';
    predictionV2.label = 'Forecast favorable vs baseline (' + _selMethod + ', MASE: ' + (Math.round(_bMASE * 100) / 100) + ')';
  } else if (_bMASE < 1.0) {
    predictionV2.mode = 'weak_model'; predictionV2.confidence = 'media';
    predictionV2.label = 'Forecast orientativo (' + _selMethod + ', MASE: ' + (Math.round(_bMASE * 100) / 100) + ')';
  } else {
    predictionV2.mode = 'observed_fallback'; predictionV2.confidence = 'baja';
    predictionV2.label = 'Forecast limitado - modelos no superan baseline (' + _selMethod + ', MASE: ' + (Math.round(_bMASE * 100) / 100) + ')';
    predictionV2.warning = 'Ningun modelo supera el baseline estacional (MASE >= 1.0). Se usa ' + _best.name + ' con confianza baja.';
  }

  predictionV2.recommended_value = _selFc;
  predictionV2.model_name = _selMethod;
  predictionV2.observed_forecast = {
    next_day: _selFc, band_low: _intervals.band_80.low, band_mid: _selFc,
    band_high: _intervals.band_80.high, next_7d_total: _horizons.next_7d.forecast, method: _selMethod
  };
  predictionV2.forecast_horizons = _horizons;
  predictionV2.intervals = _intervals;
  predictionV2.empirical_coverage_pct = _empCov;
  predictionV2.backtest = {
    window_days: _btWin, naive_mae: Math.round(_naiveMAE * 100) / 100,
    models: _ranked.map(m => ({ name: m.name, mae: Math.round(m.mae * 100) / 100, mase: Math.round(m.mase * 1000) / 1000, rmse: Math.round(m.rmse * 100) / 100 })),
    selected: _selMethod, ensemble_weights: _useEns ? _ensW : null
  };
  predictionV2.seasonal_indices = _sIdx.map((s, i) => ({ day: ['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][i], index: Math.round(s * 1000) / 1000 }));
  predictionV2.diagnostics = {
    total_history_days: _n, backtest_days: _btWin, best_model: _best.name,
    best_mase: Math.round(_best.mase * 1000) / 1000, ensemble_used: _useEns,
    coverage_80: _empCov,
    interval_width_pct: _selFc > 0 ? Math.round((_intervals.band_80.high - _intervals.band_80.low) / _selFc * 10000) / 100 : 0
  };
  if (projections.p50 > 0) {
    predictionV2.ema_crosscheck = {
      p5: projections.p5, p50: projections.p50, p95: projections.p95,
      within_range: _selFc >= projections.p5 && _selFc <= projections.p95
    };
  }


  // --- CUSUM Changepoint Detection ---
  const _cusumData = { detected: false };
  if (_n >= 14) {
    const _cusTarget = _volMean;
    let _cusPos = 0, _cusNeg = 0;
    const _cusK = 0.5 * _volStd;
    const _cusH = 4 * _volStd;
    let _cusChangeIdx = -1, _cusDir = '';

    for (let ci = 0; ci < _n; ci++) {
      _cusPos = Math.max(0, _cusPos + _vols[ci] - _cusTarget - _cusK);
      _cusNeg = Math.max(0, _cusNeg - _vols[ci] + _cusTarget - _cusK);
      if (_cusPos > _cusH) { _cusChangeIdx = ci; _cusDir = 'upward'; _cusPos = 0; }
      if (_cusNeg > _cusH) { _cusChangeIdx = ci; _cusDir = 'downward'; _cusNeg = 0; }
    }

    if (_cusChangeIdx >= _n - 10) {
      _cusumData.detected = true;
