    if (p.p5 !== undefined) ni += '\nEscenarios EMA (referencia): pesimista ' + p.p5 + ' | base ' + p.p50 + ' | optimista ' + p.p95;
  }
  if (pv2.seasonal_indices) ni += '\nIndices estacionales: ' + pv2.seasonal_indices.map(function(s) { return s.day + '=' + s.index; }).join(', ');
  if (pv2.changepoint && pv2.changepoint.detected) {
    var _cpDir = pv2.changepoint.direction === 'upward' ? 'incremento' : 'descenso';
    ni += '\nALERTA CAMBIO DE REGIMEN: ' + _cpDir + ' (' + (pv2.changepoint.shift_pct >= 0 ? '+' : '') + pv2.changepoint.shift_pct + '%) el ' + pv2.changepoint.change_date + '. Media pre=' + pv2.changepoint.pre_mean + ', post=' + pv2.changepoint.post_mean;
  }
}

ni += '\n\n--- CONVERSION Y EMBUDO ---';
if (f.available) {
  if (f.global_conversion_pct !== null) ni += '\nConversion global del embudo: ' + f.global_conversion_pct + '% (benchmark B2C saludable: >' + TH.conversion_info + '%)';
  if (f.markov_analysis && f.markov_analysis.available) {
    ni += '\nPasos esperados hasta resolucion: ' + f.markov_analysis.entry_expected_steps;
    if (f.markov_analysis.entry_step_cv !== undefined) ni += ' (CV: ' + f.markov_analysis.entry_step_cv + ', stddev: ' + f.markov_analysis.entry_step_stddev + ' pasos)';
    if (f.markov_analysis.entry_step_variance !== undefined) ni += '\nVarianza de absorcion: ' + f.markov_analysis.entry_step_variance + ' — ' + (f.markov_analysis.entry_step_cv > 1.5 ? 'ALTA: ciclo de ventas impredecible' : f.markov_analysis.entry_step_cv > 1.0 ? 'MODERADA: variabilidad significativa' : 'CONTROLADA: proceso estable');
  }
  ni += '\nObjetivo final: llegar a ' + f.conversion_target;
}

ni += '\n\n--- FEEDERS: ESTADOS QUE APORTAN LEADS A CONVERSION (DATO POSITIVO) ---';
ni += '\nIMPORTANTE: Los feeders son estados BUENOS. Son el camino que los leads toman para llegar a conversion. NO son fugas.';
if (f.available && f.feeders && f.feeders.length > 0) {
  f.feeders.slice(0, 5).forEach(function(fe) { ni += '\n  FEEDER: ' + fe.from + ' -> aporta ' + fe.pct + '% de los leads a conversion (' + fe.cnt + ' leads convierten desde aqui)'; });
} else {
  ni += '\n  Sin feeders identificados.';
}

ni += '\n\n--- FUGAS: DONDE SE PIERDEN LEADS (DATO NEGATIVO) ---';
ni += '\nIMPORTANTE: Las fugas son estados MALOS. Son transiciones donde los leads se PIERDEN y NO convierten.';
if (f.available && f.biggest_leak) {
  ni += '\n  FUGA PRINCIPAL: de ' + f.biggest_leak.from + ' a ' + f.biggest_leak.to + ' (' + f.biggest_leak.pct + '%, ' + f.biggest_leak.cnt + ' leads se PIERDEN aqui)';
  if (f.top_leaks && f.top_leaks.length > 1) {
    f.top_leaks.slice(1, 4).forEach(function(l) { ni += '\n  FUGA: ' + l.from + ' -> ' + l.to + ': ' + l.pct + '% (' + l.cnt + ' leads PERDIDOS)'; });
  }
} else {
  ni += '\n  No se detectaron fugas por encima del umbral configurado (' + TH.leak_warning_pct + '%) en este periodo. El analisis Markov y Revenue at Risk pueden revelar fugas menores no cubiertas por esta regla.';
}

ni += '\n\n--- ESTADOS TRAMPA (leads atascados sin avanzar) ---';
if (f.available && f.trap_states && f.trap_states.length > 0) {
  f.trap_states.forEach(function(t) { ni += '\n  TRAMPA: ' + t.state + ': ' + t.leads + ' leads atrapados (' + t.self_pct + '% no avanzan)'; });
} else {
  ni += '\n  Sin estados trampa detectados.';
}

if (f.available) {
  if (f.revenue_at_risk && f.revenue_at_risk.length > 0) {
    ni += '\n\n--- REVENUE AT RISK ---';
    ni += '\nTotal revenue at risk: $' + (f.total_revenue_at_risk || 0).toLocaleString();
    f.revenue_at_risk.slice(0, 3).forEach(function(r) {
      ni += '\n  - ' + r.from + ' -> ' + r.to + ': ' + r.leads_lost + ' leads, $' + r.revenue_at_risk.toLocaleString() + ' en riesgo';
    });
  }
  if (f.markov_analysis && f.markov_analysis.available) {
    ni += '\n\n--- ANALISIS DE MARKOV ---';
    ni += '\nEstados absorbentes: ' + f.markov_analysis.absorbing_states.join(', ');
    ni += '\nProbabilidades de absorcion:';
    f.markov_analysis.absorption_probabilities.forEach(function(ap) {
      ni += '\n  ' + ap.state + ': prob_conversion=' + (ap.prob_conversion !== null ? (ap.prob_conversion * 100).toFixed(2) + '%' : 'N/A') + ', pasos=' + ap.expected_steps;
    });
  }
}

ni += '\n\n--- OPERACIONES ---';
if (o.available) {
  ni += '\nTotal leads periodo: ' + o.total_leads + ' en ' + o.total_days + ' dias (promedio: ' + o.avg_daily + '/dia)';
  ni += '\nUltimo dia: ' + o.latest.date + ' con ' + o.latest.leads + ' leads';
  ni += '\nRango diario: ' + o.min_daily + ' - ' + o.max_daily;
  if (o.last_7d_avg) ni += '\nPromedio 7d: ' + o.last_7d_avg + ' (anterior: ' + o.prev_7d_avg + ', cambio: ' + o.wow_change_pct + '%)';
  ni += '\nTendencia reciente: ' + o.recent_trend;
  if (o.peak_hour !== undefined) ni += '\nHora pico: ' + o.peak_hour + ':00, hora valle: ' + o.valley_hour + ':00';
  if (o.call_records) {
    ni += '\n\n--- METRICAS DE LLAMADAS (' + (o.call_data_note || 'Pre-agregado de ' + o.call_records + ' registros') + ') ---';
    if (o.unique_contacts) ni += '\nContactos unicos: ' + o.unique_contacts;
    if (o.call_metrics && o.call_metrics.call_duration) ni += '\nDuracion de llamada: promedio ' + o.call_metrics.call_duration.avg + ' seg, min ' + o.call_metrics.call_duration.min + ', max ' + o.call_metrics.call_duration.max;
    if (o.call_metrics && o.call_metrics.minutes_since_prev) ni += '\nIntervalo entre intentos: promedio ' + o.call_metrics.minutes_since_prev.avg + ' min, min ' + o.call_metrics.minutes_since_prev.min + ', max ' + o.call_metrics.minutes_since_prev.max;
    if (o.call_metrics && o.call_metrics.call_rank) ni += '\nNumero de intento promedio: ' + o.call_metrics.call_rank.avg + ' (rango: ' + o.call_metrics.call_rank.min + '-' + o.call_metrics.call_rank.max + ')';
    if (o.contact_distribution) {
      ni += '\nDistribucion de intentos:';
      ni += '\n  Primer intento: ' + o.contact_distribution.first_attempts + ' llamadas';
      ni += '\n  Intentos 1-3 (sweet spot): ' + o.contact_distribution.attempts_1_to_3 + ' llamadas';
      ni += '\n  Intentos 1-5: ' + o.contact_distribution.attempts_1_to_5 + ' llamadas';
      ni += '\n  Sobre-contacto (>7 intentos): ' + o.contact_distribution.overcontact_calls + ' llamadas (' + o.contact_distribution.overcontact_pct + '%)';
    }
  }
}

if (ll.available) {
  ni += '\n\n--- CAPACIDAD OPERATIVA (Little\'s Law) ---';
  ni += '\nLeads en sistema (WIP): ' + ll.L_wip + ' | Capacidad maxima: ' + ll.max_capacity;
  ni += '\nUtilizacion: ' + ll.capacity_utilization_pct + '%';
  ni += '\nEstado: ' + (ll.saturated ? 'SATURADO' : 'Dentro de capacidad');
}

ni += '\n\n--- INVERSION ---';
if (inv.available) {
  ni += '\nGasto total: $' + Math.round(inv.total_spend).toLocaleString() + ' | Campanas: ' + inv.campaign_count;
  if (inv.top_spender) ni += '\nMayor gasto: ' + inv.top_spender.name + ' ($' + Math.round(inv.top_spender.spend).toLocaleString() + ', ' + inv.top_concentration_pct + '%)';
  inv.campaigns.forEach(function(c) { ni += '\n  ' + c.name + ': $' + Math.round(c.spend).toLocaleString() + ' (' + c.pct_of_total + '%)'; });
  if (cpl.available) {
    ni += '\n\n--- CPL IMPLICITO ---';
    ni += '\nCPL global: $' + cpl.global_cpl;
    if (cpl.cpl_7d_avg) ni += '\nCPL 7d promedio: $' + cpl.cpl_7d_avg + ' (anterior: $' + cpl.cpl_prev_7d_avg + ', cambio: ' + cpl.cpl_wow_change_pct + '%)';
  }
  if (inv.mmm && inv.mmm.available) {
    ni += '\n\n--- ATRIBUCION (MMM) ---';
    ni += '\nHHI: ' + inv.mmm.hhi_index + ' (' + inv.mmm.hhi_label + ')';
    ni += '\nContribucion gasto a varianza: ' + inv.mmm.spend_variance_contribution_pct + '%';
    if (inv.mmm.causal_campaigns.length > 0) ni += '\nCampanas causales (Granger): ' + inv.mmm.causal_campaigns.join(', ');
    if (inv.mmm.non_causal_campaigns.length > 0) ni += '\nCampanas SIN evidencia causal: ' + inv.mmm.non_causal_campaigns.join(', ');
  }
}

ni += '\n\n--- ALERTAS (por RPN score) ---';
alerts.forEach(function(a, i) {
  ni += '\n' + (i+1) + '. [' + a.severity.toUpperCase() + ' | RPN:' + (a.rpn_score || 0) + '] ' + a.title + ' | ' + a.impact;
});

ni += '\n\n--- ACCIONES RECOMENDADAS ---';
var _wc = alerts.filter(function(a) { return a.severity === 'warning'; }).length;
if (actions.length === 0 && _wc === 0) ni += '\nNo hay acciones urgentes en este momento. El sistema opera dentro de parametros normales.';
if (actions.length === 0 && _wc > 0) ni += '\nNo se generaron acciones criticas, pero existen ' + _wc + ' alertas de atencion. Se recomienda revision preventiva de los puntos senalados en la seccion de alertas.';
actions.forEach(function(a, i) {
  ni += '\n' + (i+1) + '. [' + a.urgency + '] ' + a.action + ' | Razon: ' + a.reason + ' | Evidencia: ' + a.evidence + ' | Impacto: ' + a.impact_est + ' | Responsable: ' + a.owner + ' | Plazo: ' + a.horizon;
});

ni += '\n\n--- DATOS TECNICOS ---';
if (p.available) ni += '\nR2: ' + p.r2 + ' | Pendiente: ' + p.slope + ' | Intercepto: ' + p.intercept + ' | Spread pct: ' + p.spread_pct + '%';
if (pv2.backtest) {
  ni += '\nBacktest (' + pv2.backtest.window_days + ' dias): Naive MAE=' + pv2.backtest.naive_mae;
  pv2.backtest.models.forEach(function(m) { ni += '\n  ' + m.name + ': MAE=' + m.mae + ', MASE=' + m.mase + ', RMSE=' + m.rmse; });
  ni += '\nModelo seleccionado: ' + pv2.backtest.selected;
  if (pv2.backtest.ensemble_weights) ni += '\nPesos ensemble: ' + pv2.backtest.ensemble_weights.map(function(w) { return w.name + '=' + w.weight; }).join(', ');
  ni += '\nCobertura empirica 80%: ' + (pv2.empirical_coverage_pct || 'N/A') + '%';
}
ni += '\nHealth Score: ' + shs + '/100';
ni += '\nFuentes: regresion=' + (facts.data_quality.sources.regresion || 0) + ', ema=' + (facts.data_quality.sources.ema || 0) + ', markov=' + (facts.data_quality.sources.markov || 0) + ', llamadas=' + (facts.data_quality.sources.llamadas || 0) + ', llegadas=' + (facts.data_quality.sources.llegadas || 0) + ', horarios=' + (facts.data_quality.sources.horarios || 0) + ', inversiones=' + (facts.data_quality.sources.inversiones || 0);

var critCount = alerts.filter(function(a) { return a.severity === 'critical'; }).length;
var warnCount = alerts.filter(function(a) { return a.severity === 'warning'; }).length;

return [{ json: {
  facts: facts,
  alerts: alerts,
  actions: actions,
  system_status: status,
  narrative_input: ni,
  alert_count: { critical: critCount, warning: warnCount, total: alerts.length },
  action_count: actions.length,
  system_health_score: shs
}}];

// === NARRATIVE QA GATE v6 ===
// Validates structural quality + semantic correctness per audience.
// Detects feeder/fuga confusion, typos, format violations.

const allNarratives = items.map(i => i.json);
const issues = [];
const qaChecks = [];

function getText(obj) {
  return obj.output || obj.response || obj.text || JSON.stringify(obj);
}

const narratives = allNarratives.map((n, i) => {
  const text = getText(n);
  const itemIssues = [];
  if (!text || text.length < 100) itemIssues.push('Narrative ' + (i+1) + ': too short (' + (text ? text.length : 0) + ' chars)');
  if (text && text.length > 8000) itemIssues.push('Narrative ' + (i+1) + ': unusually long (' + text.length + ' chars)');
  return { index: i, text: text || '', length: text ? text.length : 0, issues: itemIssues };
});

narratives.forEach(n => issues.push(...n.issues));

// --- Semantic QA: Manager feeder/fuga confusion detection ---
const mgrText = (narratives[1] && narratives[1].text) || '';
const mgrLower = mgrText.toLowerCase();

// Get feeder state names from RulesEngine data
var feederNames = [];
try {
  var rulesData = $('RulesEngine').first().json;
  var funnel = (rulesData.facts && rulesData.facts.funnel) || {};
  if (funnel.feeders) feederNames = funnel.feeders.slice(0, 5).map(function(fe) { return fe.from.toLowerCase(); });
} catch(e) {}

// Check if manager text calls any feeder a 'fuga'
var feederFugaConfusion = false;
feederNames.forEach(function(fname) {
  var fnameClean = fname.replace(/[^a-z0-9]/g, ' ').trim();
  if (fnameClean.length < 3) return;
  var regex = new RegExp('fuga[^.]{0,40}' + fnameClean.replace(/ /g, '.{0,5}'), 'i');
  if (regex.test(mgrText)) {
    feederFugaConfusion = true;
    issues.push('SEMANTIC_FAIL: Manager llama fuga al feeder ' + fname);
  }
});

qaChecks.push({ check: 'manager_feeder_fuga', passed: !feederFugaConfusion, detail: feederFugaConfusion ? 'Feeder clasificado como fuga' : 'OK' });

// --- Semantic QA: Analyst typo detection ---
const analystText = (narratives[3] && narratives[3].text) || '';
const typoPatterns = ['Res[0', 'variania', 'Utilinea', 'asionan', 'Hallazos'];
var analystTypos = [];
typoPatterns.forEach(function(tp) {
  if (analystText.includes(tp)) analystTypos.push(tp);
});
if (analystTypos.length > 0) issues.push('TYPO_WARN: Analyst tiene typos: ' + analystTypos.join(', '));
qaChecks.push({ check: 'analyst_typos', passed: analystTypos.length === 0, detail: analystTypos.length > 0 ? analystTypos.join(', ') : 'OK' });

// --- Semantic QA: Operations format (exactly 5 bullets) ---
const opsText = (narratives[2] && narratives[2].text) || '';
const bulletCount = (opsText.match(/^- /gm) || []).length;
var opsFormatOk = bulletCount === 5;
if (!opsFormatOk && bulletCount > 0) issues.push('FORMAT_WARN: Operations tiene ' + bulletCount + ' bullets (esperado: 5)');
qaChecks.push({ check: 'operations_format', passed: opsFormatOk, detail: bulletCount + ' bullets' });

// --- v6: Semantic QA — Changepoint direction consistency ---
var rulesDataQA = {};
try { rulesDataQA = $('RulesEngine').first().json; } catch(e) {}
var cpData = (rulesDataQA.facts && rulesDataQA.facts.predictionV2 && rulesDataQA.facts.predictionV2.changepoint) || {};
if (cpData.detected) {
  var execText = (narratives[0] && narratives[0].text) || '';
  var mgrTextQA = (narratives[1] && narratives[1].text) || '';
  var execLower = execText.toLowerCase();
  var mgrLowerQA = mgrTextQA.toLowerCase();
  if (cpData.direction === 'upward' && (execLower.includes('descenso') || execLower.includes('caida') || execLower.includes('disminucion'))) {
    issues.push('SEMANTIC_WARN: Executive dice descenso/caida pero changepoint es upward (+' + cpData.shift_pct + '%)');
    qaChecks.push({ check: 'exec_changepoint_consistency', passed: false, detail: 'Direction mismatch: upward vs descenso' });
  }
  if (cpData.direction === 'downward' && (execLower.includes('incremento') || execLower.includes('crecimiento') || execLower.includes('aumento'))) {
    issues.push('SEMANTIC_WARN: Executive dice incremento pero changepoint es downward (' + cpData.shift_pct + '%)');
    qaChecks.push({ check: 'exec_changepoint_consistency', passed: false, detail: 'Direction mismatch: downward vs incremento' });
  }
}

// --- v6: Semantic QA — R2/MASE consistency in analyst ---
var pv2QA = (rulesDataQA.facts && rulesDataQA.facts.predictionV2) || {};
if (pv2QA.quality_label === 'superior' && analystText.toLowerCase().includes('no funcional')) {
  var maseVal = (pv2QA.diagnostics && pv2QA.diagnostics.best_mase) || 'N/A';
  issues.push('SEMANTIC_WARN: Analyst marca modelo como NO FUNCIONAL pero MASE=' + maseVal + ' indica rendimiento superior. Usar lenguaje matizado.');
  qaChecks.push({ check: 'analyst_r2_mase_consistency', passed: false, detail: 'MASE superior pero R2 etiquetado como NO FUNCIONAL' });
}

// --- v6: Semantic QA — Minimum KPIs per audience ---
var execHtml = (narratives[0] && narratives[0].text) || '';
if (execHtml.length > 200) {
  var execHasDecision = execHtml.toLowerCase().includes('recomend') || execHtml.toLowerCase().includes('accion') || execHtml.toLowerCase().includes('decision');
  if (!execHasDecision) {
    issues.push('FORMAT_WARN: Executive narrative sin recomendaciones o acciones detectables');
    qaChecks.push({ check: 'exec_has_actions', passed: false, detail: 'Sin keywords de accion' });
  }
}

// --- v6: Semantic QA — Analyst code block integrity ---
if (analystText.includes('sql') && analystText.includes('SELECT')) {
  var fenceMarker = String.fromCharCode(96,96,96);
  var brokenFences = analystText.split(fenceMarker).length - 1;
  if (brokenFences % 2 !== 0) {
    issues.push('FORMAT_WARN: Analyst tiene bloques de codigo con fences desbalanceados (' + brokenFences + ' backtick-triples)');
    qaChecks.push({ check: 'analyst_code_integrity', passed: false, detail: brokenFences + ' fences (impar)' });
  }
}

var hasCriticalFail = issues.some(function(i) { return i.startsWith('SEMANTIC_FAIL'); });

const validation = {
  narratives_received: narratives.length,
  expected: 4,
  all_present: narratives.length >= 4,
  issues: issues,
  qa_checks: qaChecks,
  has_critical_fail: hasCriticalFail,
  is_valid: !hasCriticalFail && issues.length === 0 && narratives.length >= 4,
  has_observations: issues.filter(function(i) { return i.includes('TYPO_WARN') || i.includes('FORMAT_WARN') || i.includes('unusually'); }).length > 0
};

return [{
  json: {
    validation: validation,
    executive_report: narratives[0] ? narratives[0].text : '',
    manager_report: narratives[1] ? narratives[1].text : '',
    analyst_report: narratives[3] ? narratives[3].text : '',
    operations_briefing: narratives[2] ? narratives[2].text : '',
    all_narratives: narratives
  }
}];

// === FINAL REPORT BUNDLE v7 ===
var data = $input.first().json;
var rulesData = $('RulesEngine').first().json;
var facts = rulesData.facts || {};
var alerts = rulesData.alerts || [];
var actions = rulesData.actions || [];
var systemStatus = rulesData.system_status || { color: 'verde', label: 'Sin datos', shs: 100 };
var shs = rulesData.system_health_score || 100;

var kpis = [];
var o = facts.operations || {};
var p = facts.projections || {};
var inv = facts.investment || {};
var pv2 = facts.predictionV2 || {};
var f = facts.funnel || {};
var ll = facts.littles_law || {};
var cpl = facts.cpl_analysis || {};

// Health Score KPI (always first)
kpis.push({
  value: shs + '/100',
  label: 'Health Score',
  sub: systemStatus.label,
  color: shs >= 80 ? 'green' : shs >= 65 ? '' : 'red'
});

if (o.available) {
  kpis.push({ value: (o.total_leads || 0).toLocaleString(), label: 'Leads totales', sub: o.total_days + ' dias' });
  kpis.push({ value: Math.round(o.avg_daily).toString(), label: 'Promedio diario', sub: 'leads/dia' });
  if (o.wow_change_pct !== undefined) {
    var sign = o.wow_change_pct >= 0 ? '+' : '';
    kpis.push({ value: sign + o.wow_change_pct + '%', label: 'Cambio semanal', sub: 'vs semana anterior', color: o.wow_change_pct >= 0 ? 'green' : 'red' });
  }
  if (o.peak_hour !== undefined) kpis.push({ value: o.peak_hour + ':00', label: 'Hora pico', sub: 'mayor volumen' });
}

// Conversion KPI
if (f.global_conversion_pct !== undefined && f.global_conversion_pct !== null) {
  kpis.push({
    value: f.global_conversion_pct + '%',
    label: 'Conversion global',
    sub: 'entrada a cierre',
    color: f.global_conversion_pct >= 3.0 ? 'green' : f.global_conversion_pct >= 2.0 ? '' : 'red'
  });
}

if (pv2.recommended_value) {
  kpis.push({ value: '~' + pv2.recommended_value, label: 'Prevision diaria', sub: (pv2.model_name || '') + ' | ' + (pv2.confidence || '') });
  if (pv2.diagnostics && pv2.diagnostics.best_mase !== null && pv2.diagnostics.best_mase !== undefined) {
    kpis.push({ value: String(pv2.diagnostics.best_mase), label: 'MASE', sub: pv2.diagnostics.best_mase < 1 ? 'supera baseline' : 'no supera baseline', color: pv2.diagnostics.best_mase < 1 ? 'green' : 'red' });
  }
}

// Revenue at Risk KPI
if (f.total_revenue_at_risk && f.total_revenue_at_risk > 0) {
  kpis.push({
    value: '$' + f.total_revenue_at_risk.toLocaleString(),
    label: 'Revenue at Risk',
    sub: 'en fugas del embudo',
    color: f.total_revenue_at_risk > 5000 ? 'red' : ''
  });
}

// Little's Law WIP
if (ll.available) {
  kpis.push({
    value: ll.capacity_utilization_pct + '%',
    label: 'Utilizacion capacidad',
    sub: ll.L_wip + '/' + ll.max_capacity + ' WIP',
    color: ll.saturated ? 'red' : ll.capacity_utilization_pct > 85 ? '' : 'green'
  });
}

// CPL
if (cpl.available && cpl.global_cpl) {
  kpis.push({
    value: '$' + cpl.global_cpl,
    label: 'CPL implicito',
    sub: cpl.cpl_wow_change_pct !== undefined ? (cpl.cpl_wow_change_pct >= 0 ? '+' : '') + cpl.cpl_wow_change_pct + '% WoW' : 'global',
    color: cpl.cpl_wow_change_pct > 20 ? 'red' : 'green'
  });
}

// Investment
if (inv.available && inv.total_spend) {
  kpis.push({ value: '$' + Math.round(inv.total_spend).toLocaleString(), label: 'Gasto total', sub: inv.campaign_count + ' campanas' });
  if (inv.mmm && inv.mmm.hhi_index) {
    kpis.push({ value: String(inv.mmm.hhi_index), label: 'HHI', sub: inv.mmm.hhi_label, color: inv.mmm.hhi_index > 0.25 ? 'red' : inv.mmm.hhi_index > 0.15 ? '' : 'green' });
  }
}

// Changepoint
if (pv2.changepoint && pv2.changepoint.detected) {
  kpis.push({ value: (pv2.changepoint.shift_pct >= 0 ? '+' : '') + pv2.changepoint.shift_pct + '%', label: 'Cambio regimen', sub: pv2.changepoint.change_date, color: Math.abs(pv2.changepoint.shift_pct) > 20 ? 'red' : 'green' });
