function mdToHtml(md) {
  if (!md) return '<p class="empty-state">Sin contenido disponible.</p>';
  let html = md;
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/```([\s\S]*?)```/g, '<pre style="background:#f8fafc;padding:12px;border-radius:6px;font-size:12px;overflow-x:auto;border:1px solid #e2e8f0"><code>$1</code></pre>');
  const lines = html.split('\n');
  let inTable = false, headerDone = false, inList = false, _lt = 'ol';
  const out = [];
  for (const rawLine of lines) {
    const t = rawLine.trim();
    if (t.startsWith('|') && t.endsWith('|')) {
      if (inList) { out.push('</' + _lt + '>'); inList = false; }
      if (!inTable) { out.push('<div class="tbl-wrap"><table>'); inTable = true; headerDone = false; }
      if (t.replace(/[\|\-\s\:]/g, '') === '') continue;
      const cells = t.split('|').filter(c => c.trim());
      const tag = !headerDone ? 'th' : 'td';
      out.push('<tr>' + cells.map(c => '<' + tag + '>' + c.trim() + '</' + tag + '>').join('') + '</tr>');
      if (!headerDone) headerDone = true;
    } else {
      if (inTable) { out.push('</table></div>'); inTable = false; }
      if (/^\d+\.\s/.test(t)) {
        if (!inList) { _lt = 'ol'; out.push('<ol>'); inList = true; }
        out.push('<li>' + t.replace(/^\d+\.\s/, '') + '</li>');
      } else if (/^[-*]\s/.test(t)) {
        if (!inList) { _lt = 'ul'; out.push('<ul>'); inList = true; }
        out.push('<li>' + t.replace(/^[-*]\s/, '') + '</li>');
      } else {
        if (inList) { out.push('</' + _lt + '>'); inList = false; }
        if (!t) out.push('<br/>');
        else if (t === '---' || t === '***') out.push('<hr style="border:none;border-top:1px solid #e2e8f0;margin:16px 0"/>');
        else if (t.startsWith('### ')) out.push('<p style="font-size:14px;font-weight:700;margin:16px 0 8px;color:var(--p)">' + t.slice(4) + '</p>');
        else if (t.startsWith('## ')) out.push('<p style="font-size:16px;font-weight:800;margin:20px 0 10px;color:var(--p)">' + t.slice(3) + '</p>');
        else out.push('<p>' + t + '</p>');
      }
    }
  }
  if (inTable) out.push('</table></div>');
  if (inList) out.push('</' + _lt + '>');
  return out.join('\n');
}

function sevColor(sev) {
  return sev === 'critical' ? '#e53e3e' : sev === 'warning' ? '#dd6b20' : '#3182ce';
}
function sevBg(sev) {
  return sev === 'critical' ? '#fff5f5' : sev === 'warning' ? '#fffaf0' : '#ebf8ff';
}
function sevLabel(sev) {
  return sev === 'critical' ? 'CRITICO' : sev === 'warning' ? 'ALERTA' : 'INFO';
}
function urgColor(u) {
  return u === 'immediate' ? '#e53e3e' : u === 'this_week' ? '#dd6b20' : '#38a169';
}
function urgLabel(u) {
  return u === 'immediate' ? 'INMEDIATO' : u === 'this_week' ? 'ESTA SEMANA' : 'ESTE MES';
}

function statusClass() {
  return sysStatus.color === 'rojo' ? 'status-red' : sysStatus.color === 'amarillo' ? 'status-yellow' : 'status-green';
}
