  }).join('') + '</div>';
}

function buildAlertCards() {
  const meaningful = alerts.filter(a => a.severity !== 'info');
  const infos = alerts.filter(a => a.severity === 'info');
  let html = '';
  if (meaningful.length === 0 && infos.length === 0) return '<div class="empty-card"><p>No hay alertas activas. El sistema opera dentro de parametros normales.</p></div>';
  meaningful.forEach(a => {
    html += '<div class="alert-card" style="border-left:4px solid ' + sevColor(a.severity) + ';background:' + sevBg(a.severity) + '"><div class="alert-badge" style="background:' + sevColor(a.severity) + '">' + sevLabel(a.severity) + '</div><div class="alert-title">' + a.title + '</div><div class="alert-detail">' + (a.impact || '') + '</div></div>';
  });
  if (infos.length > 0) {
    html += '<div class="info-section"><div class="info-header" onclick="this.parentElement.classList.toggle(\'open\')">Informacion adicional (' + infos.length + ') <span class="chevron">+</span></div><div class="info-body">';
    infos.forEach(a => { html += '<div class="info-item"><strong>' + a.title + '</strong><br/><span class="info-impact">' + (a.impact || '') + '</span></div>'; });
    html += '</div></div>';
  }
  return html;
}

function buildActionCards() {
  if (actions.length === 0) return '<div class="empty-card"><p>No hay acciones urgentes pendientes.</p></div>';
  return actions.map((a, i) => {
    return '<div class="action-card" style="border-left:4px solid ' + urgColor(a.urgency) + '"><div class="action-head"><span class="action-num">' + (i + 1) + '</span><span class="action-badge" style="background:' + urgColor(a.urgency) + '">' + urgLabel(a.urgency) + '</span></div><div class="action-text">' + a.action + '</div><div class="action-meta"><span>Razon: ' + (a.reason || '') + '</span></div><div class="action-meta"><span>Responsable: ' + (a.owner || '-') + '</span><span>Plazo: ' + (a.horizon || '-') + '</span></div></div>';
  }).join('');
}

function predBadge() {
  const method = structured.prediction_method || '';
  const mase = structured.prediction_mase;
  const maseStr = mase !== null && mase !== undefined ? ' (MASE: ' + mase + ')' : '';
