// === DASHBOARD PAYLOAD BUILDER v7 ===
// Produces a single JSON optimized for the Netlify dashboard frontend.

const bundle = $('FinalReportBundle').first().json;
const docs = $('DocumentGenerator').all();
const rulesData = $('RulesEngine').first().json;
const facts = rulesData.facts || {};

const pv2 = facts.predictionV2 || {};
const f = facts.funnel || {};
const o = facts.operations || {};
const inv = facts.investment || {};
const ll = facts.littles_law || {};
const cpl = facts.cpl_analysis || {};

const payload = {
  meta: {
    generated_at: bundle._generated_at || new Date().toISOString(),
    version: '7.0',
    execution_id: 'exec_' + Date.now()
  },
  system: {
    health_score: bundle.structured ? bundle.structured.system_health_score : 0,
    status: bundle.structured ? bundle.structured.system_status : { color: 'verde', label: 'Sin datos' },
    alerts: rulesData.alerts || [],
    actions: rulesData.actions || []
  },
  kpis: bundle.structured ? bundle.structured.kpis : [],
  forecast: {
    recommended_value: pv2.recommended_value || null,
    method: pv2.model_name || null,
    mase: pv2.diagnostics ? pv2.diagnostics.best_mase : null,
    confidence: pv2.confidence || null,
    quality_label: pv2.quality_label || null,
    r2: facts.projections ? facts.projections.r2 : null,
    slope: facts.projections ? facts.projections.slope : null,
    intervals: pv2.intervals || {},
    horizons: pv2.forecast_horizons || {},
    backtest_models: pv2.backtest ? pv2.backtest.models : [],
    seasonal_indices: pv2.seasonal_indices || [],
    changepoint: pv2.changepoint || { detected: false },
    time_series: facts.raw_time_series || []
  },
  funnel: {
    conversion_pct: f.global_conversion_pct || null,
    conversion_target: f.conversion_target || 'Consult Booked',
    transitions: facts.raw_transitions || [],
    feeders: f.feeders || [],
    leaks: f.top_leaks || [],
    trap_states: f.trap_states || [],
    absorption_probabilities: f.markov_analysis && f.markov_analysis.available ? f.markov_analysis.absorption_probabilities : [],
    revenue_at_risk: f.revenue_at_risk || []
  },
  operations: {
    total_leads: o.total_leads || 0,
    total_days: o.total_days || 0,
    avg_daily: o.avg_daily || 0,
    latest: o.latest || null,
    min_daily: o.min_daily || 0,
    max_daily: o.max_daily || 0,
    wow_change_pct: o.wow_change_pct || 0,
    last_7d_avg: o.last_7d_avg || 0,
    prev_7d_avg: o.prev_7d_avg || 0,
    peak_hour: o.peak_hour || null,
    valley_hour: o.valley_hour || null,
    daily_volumes: (facts.raw_time_series || []).map(function(d) { return { date: d.date, leads: d.value }; }),
    hourly_distribution: (facts.raw_hourly || []).map(function(h, i) {
      var hKeys = Object.keys(h);
      var hF = hKeys.find(function(k) { return k.toLowerCase().includes('hora') || k.toLowerCase().includes('hour'); }) || hKeys[0];
      var vF = hKeys.find(function(k) { return k !== hF && typeof h[k] === 'number'; }) || hKeys[1];
      return { hour: h[hF], probability: parseFloat(h[vF]) || 0, label: String(h[hF]).padStart(2,'0') + ':00' };
    }),
    call_metrics: o.call_metrics ? {
      total_records: o.call_records || 0,
      unique_contacts: o.unique_contacts || 0,
