    hhi: inv.mmm ? { index: inv.mmm.hhi_index, label: inv.mmm.hhi_label } : null,
    cpl: cpl.available ? cpl : { available: false },
    mmm: inv.mmm || { available: false },
    granger: inv.mmm && inv.mmm.granger_results ? inv.mmm.granger_results : {}
  }
};

// Collect HTML reports
const reports = {};
docs.forEach(function(d) {
  var dj = d.json;
  if (dj.audience && dj.html) reports[dj.audience] = dj.html;
});

return [{ json: { payload: payload, reports: reports } }];

// === PREPARE GITHUB TREE v7 ===
// Builds the tree entries array for the GitHub Git Trees API.
// Creates a single atomic commit with all 5 files.

const data = $input.first().json;
const payload = data.payload;
const reports = data.reports || {};

const OWNER = 'Gerion9';
const REPO = 'Marketing_LOOMS';
const BRANCH = 'main';

const files = [
  { path: 'public/data/dashboard_payload.json', content: JSON.stringify(payload, null, 2) }
];

Object.entries(reports).forEach(function(entry) {
  files.push({ path: 'public/reports/reporte_' + entry[0] + '.html', content: entry[1] });
});

const tree = files.map(function(f) {
  return { path: f.path, mode: '100644', type: 'blob', content: f.content };
});

const commitMsg = 'chore: update dashboard data - ' + new Date().toISOString().split('T')[0];

return [{ json: { owner: OWNER, repo: REPO, branch: BRANCH, tree: tree, message: commitMsg } }];
